\set ON_ERROR_STOP on
BEGIN READ ONLY;
SELECT 'migration',version_num FROM public.alembic_version;
SELECT 'pointer',dataset_id,release_id FROM area_pilot.active_release ORDER BY dataset_id;
SELECT 'ct_boundary',count(*),count(*) FILTER (WHERE geom IS NOT NULL) FROM area_pilot.tract_boundary_ct_2023;
SELECT 'acs_boundary',level,count(*),count(*) FILTER (WHERE geom IS NOT NULL) FROM area_pilot.acs_boundary_2024 GROUP BY level ORDER BY level;
SELECT 'published_release',dataset_id,id,source_release_id FROM area_pilot.release WHERE status='published' ORDER BY dataset_id,id;
SELECT 'places_county_observations',count(*) FROM area_pilot.observation WHERE release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd';
SELECT 'places_tract_observations',count(*) FROM area_pilot.observation_tract WHERE release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd';
SELECT 'acs_observations',level,count(*) FROM area_pilot.observation_acs WHERE release_id='c1baba8e-ad3d-409f-b390-d312dbf19686' GROUP BY level ORDER BY level;
SELECT 'places_county_sample',county_fips,measure_id,observation_period,value,ci_low,ci_high,status FROM area_pilot.observation WHERE release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd' AND county_fips='09110' ORDER BY measure_id LIMIT 2;
SELECT 'places_tract_sample',tract_fips,measure_id,observation_period,value,ci_low,ci_high,status FROM area_pilot.observation_tract WHERE release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd' AND tract_fips LIKE '09110%' ORDER BY tract_fips,measure_id LIMIT 2;
SELECT 'acs_sample',level,geoid,measure_id,value,moe,status FROM area_pilot.observation_acs WHERE release_id='c1baba8e-ad3d-409f-b390-d312dbf19686' AND geoid IN ('09','09110') ORDER BY level,geoid LIMIT 2;
SELECT 'places_county_map_count',count(*) FROM area_pilot.observation o JOIN dim_county_boundary b ON b.location_id=o.county_fips WHERE o.release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd' AND o.measure_id='dental_crudeprev' AND o.observation_period='2022' AND o.population='adults' AND o.value_type='crude_prevalence' AND b.geom IS NOT NULL AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326));
SELECT 'places_county_table',o.county_fips,b.name,o.value,o.status FROM area_pilot.observation o JOIN dim_county_boundary b ON b.location_id=o.county_fips WHERE o.release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd' AND o.measure_id='dental_crudeprev' AND o.observation_period='2022' AND o.population='adults' AND o.value_type='crude_prevalence' AND b.geom IS NOT NULL AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326)) ORDER BY o.county_fips LIMIT 3;
SELECT 'places_tract_map_count',count(*) FROM area_pilot.observation_tract o JOIN area_pilot.tract_boundary_ct_2023 b ON b.tract_fips=o.tract_fips WHERE o.release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd' AND o.measure_id='dental_crudeprev' AND o.observation_period='2022' AND o.population='adults' AND o.value_type='crude_prevalence' AND b.geom IS NOT NULL AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326));
SELECT 'places_tract_table',o.tract_fips,b.name,o.value,o.status FROM area_pilot.observation_tract o JOIN area_pilot.tract_boundary_ct_2023 b ON b.tract_fips=o.tract_fips WHERE o.release_id='f735c524-3fd4-4848-bfe3-1049cbc514dd' AND o.measure_id='dental_crudeprev' AND o.observation_period='2022' AND o.population='adults' AND o.value_type='crude_prevalence' AND b.geom IS NOT NULL AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326)) ORDER BY o.tract_fips LIMIT 3;
SELECT 'acs_county_map_count',count(*) FROM area_pilot.observation_acs o JOIN area_pilot.acs_boundary_2024 b ON b.level=o.level AND b.geoid=o.geoid WHERE o.release_id='c1baba8e-ad3d-409f-b390-d312dbf19686' AND o.level='county' AND o.measure_id='B19013_001E' AND o.observation_period='2020–2024' AND o.population='households' AND o.value_type='median_household_income' AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326));
SELECT 'acs_county_table',o.geoid,b.name,o.value,o.moe,o.status FROM area_pilot.observation_acs o JOIN area_pilot.acs_boundary_2024 b ON b.level=o.level AND b.geoid=o.geoid WHERE o.release_id='c1baba8e-ad3d-409f-b390-d312dbf19686' AND o.level='county' AND o.measure_id='B19013_001E' AND o.observation_period='2020–2024' AND o.population='households' AND o.value_type='median_household_income' AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326)) ORDER BY o.geoid LIMIT 3;
SELECT 'acs_tract_map_count',count(*) FROM area_pilot.observation_acs o JOIN area_pilot.acs_boundary_2024 b ON b.level=o.level AND b.geoid=o.geoid WHERE o.release_id='c1baba8e-ad3d-409f-b390-d312dbf19686' AND o.level='tract' AND o.measure_id='B19013_001E' AND o.observation_period='2020–2024' AND o.population='households' AND o.value_type='median_household_income' AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326));
SELECT 'acs_tract_table',o.geoid,b.name,o.value,o.moe,o.status FROM area_pilot.observation_acs o JOIN area_pilot.acs_boundary_2024 b ON b.level=o.level AND b.geoid=o.geoid WHERE o.release_id='c1baba8e-ad3d-409f-b390-d312dbf19686' AND o.level='tract' AND o.measure_id='B19013_001E' AND o.observation_period='2020–2024' AND o.population='households' AND o.value_type='median_household_income' AND b.geom && ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326) AND ST_Intersects(b.geom,ST_MakeEnvelope(-73.8,40.9,-71.7,42.1,4326)) ORDER BY o.geoid LIMIT 3;
SELECT 'postgis_geometry_sample',ST_IsValid(geom),length(ST_AsGeoJSON(ST_SimplifyPreserveTopology(geom,0.04))) > 10 FROM area_pilot.acs_boundary_2024 WHERE level='county' AND geoid='09110';
SELECT 'published_source_references',count(*),count(DISTINCT sf.path) FROM area_pilot.source_file sf JOIN area_pilot.release r ON r.id=sf.release_id WHERE r.status='published';
COMMIT;
